// Read-only presentation of the deterministic controller snapshots. No sample,
// alarm, job or recovery is generated by this landing-page model.
import {
  FRAMES, INTERFACE, MAIN_ALARM, CRITICAL_ALARM, THRESHOLD,
  currentFrame, observations,
} from './model/model.js';
import { agentResponse } from './model/agentic-model.js';
import {
  DOMAINS, MONITORING_CONTEXT, domainDevices, domainLabel, summarize,
} from './model/scale.js';

const interfaceTarget = { kind: 'interface', id: `XR-P1:${INTERFACE}` };
const deviceTarget = { kind: 'device', id: 'XR-PE-E2' };

function interfaceTrend(state) {
  const source = observations(state);
  const points = FRAMES.slice(0, Math.max(0, state.frame) + 1)
    .filter(frame => frame.time <= source.observedAt)
    .map(frame => ({ time: frame.time, value: frame.utilization }));
  return points.length ? points : [{ time: source.observedAt, value: source.utilization }];
}

function gapObservation(state, domainId) {
  const main = state.gap === 'west';
  const emittingDomain = domainId === MONITORING_CONTEXT.mainDomain;
  const reading = observations(state);
  return {
    kind: 'gap', tone: 'inactive', title: 'Telemetry unavailable',
    value: main && emittingDomain ? `${reading.utilization}% last known` : 'Last known',
    detail: main ? `${emittingDomain ? 'XR-P1' : 'XR-P2'} interface metrics · Current reading unavailable` : 'Device telemetry · Reachability checked separately',
    time: main ? reading.observedAt : '07:50', source: 'Telemetry collection status',
    fresh: false, incident: 'monitoring',
    target: main ? emittingDomain ? interfaceTarget : { kind: 'interface', id: 'XR-P2:HundredGigE0/0/0/1' } : deviceTarget,
    domainId,
    ...(main && emittingDomain ? { trend: interfaceTrend(state) } : {}),
  };
}

export function domainObservation(state, domainId) {
  const exists = DOMAINS.some(domain => domain.id === domainId);
  if (!exists) return {
    kind: 'gap', tone: 'inactive', title: 'Domain unavailable',
    detail: 'This domain is not part of the selected WAN.', time: null,
    source: 'Selected WAN inventory', fresh: false, domainId,
  };
  const time = currentFrame(state).time;
  const summary = summarize(state, domainDevices(domainId));
  const isMain = domainId === MONITORING_CONTEXT.mainDomain;
  const isCritical = domainId === MONITORING_CONTEXT.criticalDomain;
  const isGap = state.gap === 'west'
    ? [MONITORING_CONTEXT.mainDomain, MONITORING_CONTEXT.transitDomain].includes(domainId)
    : state.gap === 'east' && isCritical;

  if (isCritical && state.critical) return {
    kind: 'critical', tone: 'negative', title: 'Router unreachable', value: 'XR-PE-E2',
    detail: state.gap === 'east'
      ? 'Independent reachability · Device telemetry last observed 07:50'
      : 'Independent reachability check confirmed',
    time, source: 'Independent reachability checks', fresh: true,
    incident: 'device', target: deviceTarget, domainId,
  };

  if (isMain) {
    const reading = observations(state), response = agentResponse(state);
    const alarmActive = state.frame >= 2 && state.frame < 11;
    if (alarmActive) return {
      kind: 'major', tone: 'warning', title: 'Interface alarm active',
      value: `${reading.utilization}%${reading.fresh ? '' : ' last known'}`,
      detail: reading.fresh ? `XR-P1 outbound · Threshold ${THRESHOLD}%`
        : `Major alarm remains active · Last observed ${reading.observedAt}`,
      time: reading.observedAt, source: 'Interface telemetry · CNC-1042',
      fresh: reading.fresh, trend: interfaceTrend(state), incident: 'interface',
      target: interfaceTarget, domainId,
    };
    if (isGap) return gapObservation(state, domainId);
    if (state.frame === 11) return {
      kind: 'recovery', tone: response.resolved ? 'positive' : 'warning',
      title: response.resolved ? 'Recovery verified' : 'Source alarm cleared',
      value: `${reading.utilization}%`,
      detail: response.resolved ? 'Below threshold for 5 minutes' : 'Response outcome remains unverified',
      time: reading.observedAt, source: 'Interface telemetry · Source alarm', fresh: true,
      trend: interfaceTrend(state), incident: 'interface', target: interfaceTarget, domainId,
    };
    return {
      kind: state.frame === 1 ? 'trend' : 'quiet',
      tone: state.frame === 1 ? 'info' : 'positive',
      title: state.frame === 1 ? 'Utilization rising' : 'Interface within limits',
      value: `${reading.utilization}%`, detail: `XR-P1 outbound · Threshold ${THRESHOLD}%`,
      time: reading.observedAt, source: 'Interface telemetry', fresh: true,
      trend: interfaceTrend(state), incident: 'interface', target: interfaceTarget, domainId,
    };
  }
  if (isGap) return gapObservation(state, domainId);
  if (summary.alarms) return {
    kind: 'major', tone: 'warning', title: 'Interface discard alarm',
    value: 'Minor · Active', detail: 'XR-P2 · Peer interface source', time,
    source: 'CNC-1044', fresh: true, domainId, incident: 'interface',
    target: { kind: 'interface', id: 'XR-P2:HundredGigE0/0/0/1' },
  };
  return {
    kind: 'quiet', tone: 'positive', title: 'No active source alarms',
    value: 'Reachable', detail: 'Reachability and collection current', time,
    source: 'Reachability checks · Telemetry collection', fresh: true, domainId,
  };
}

function incidentRecord(state, id) {
  const response = agentResponse(state, id), reading = observations(state);
  const device = id === 'device', collection = id === 'monitoring';
  const domainId = device ? MONITORING_CONTEXT.criticalDomain
    : collection && state.gap === 'east' ? MONITORING_CONTEXT.criticalDomain
      : MONITORING_CONTEXT.mainDomain;
  return {
    id, title: response.title, target: response.target, domainId,
    severity: device ? 'Critical' : collection ? 'Coverage gap' : state.frame < 11 ? 'Major' : 'Follow-up',
    sourceState: device ? 'Critical · Active' : collection ? 'Collection unavailable'
      : state.frame < 11 ? 'Major · Active' : 'Source-cleared',
    stage: response.stage, owner: response.owner, currentAgent: response.currentAgent,
    currentWork: response.currentWork, next: response.next,
    needsDecision: response.needsDecision, resolved: response.resolved,
    time: device ? state.criticalDetected || currentFrame(state).time
      : collection ? response.startedAt : state.frame < 11 ? '08:00' : '08:30',
    metric: !device && !collection ? {
      value: reading.utilization, unit: '%', threshold: THRESHOLD,
      fresh: reading.fresh, time: reading.observedAt,
    } : null,
    handoff: response.handoff,
  };
}

function sourceUpdate(observation, id) {
  return {
    ...observation, id,
    detail: [observation.value, observation.detail].filter(Boolean).join(' · '),
  };
}

export function networkWatch(state) {
  // The landing attention area is always the current watch. Historical source
  // views retain their separate projection in domainObservation and evidence.
  state = { ...state, history: null };
  const time = currentFrame(state).time, reading = observations(state);
  const main = agentResponse(state), incidents = [], updates = [];
  if (state.critical) incidents.push(incidentRecord(state, 'device'));
  if (state.frame >= 2 && !main.resolved) incidents.push(incidentRecord(state, 'interface'));
  if (state.gap !== 'none') incidents.push(incidentRecord(state, 'monitoring'));

  if (state.critical) updates.push(sourceUpdate(domainObservation(state, MONITORING_CONTEXT.criticalDomain), CRITICAL_ALARM));
  if (state.gap !== 'none') {
    const domainId = state.gap === 'west' ? MONITORING_CONTEXT.mainDomain : MONITORING_CONTEXT.criticalDomain;
    updates.push(sourceUpdate(gapObservation(state, domainId), 'collection-source'));
  }
  if (main.resolved) updates.push({
    id: 'interface-outcome', kind: 'recovery', tone: 'positive',
    title: 'Recovery independently verified', detail: 'Source-cleared · Below 80% for 5 minutes',
    time: '08:35', source: 'Verification criteria', fresh: true,
    domainId: MONITORING_CONTEXT.mainDomain, incident: 'interface', target: interfaceTarget,
  });
  else updates.push(sourceUpdate(domainObservation(state, MONITORING_CONTEXT.mainDomain), MAIN_ALARM));

  if (state.frame >= 2) {
    const job = main.job;
    updates.push({
      id: 'interface-response', kind: 'response',
      tone: main.resolved ? 'positive' : main.needsDecision ? 'warning' : 'in-progress',
      title: main.resolved ? 'Response outcome retained'
        : job.status === 'completed' ? 'Controller job completed'
          : job.status === 'running' ? 'Controller job running'
            : job.status === 'failed' ? 'Controller job failed'
              : job.status === 'unknown' ? 'Controller result unconfirmed'
                : main.currentAgent,
      detail: main.resolved ? 'Confirmed execution and source evidence retained'
        : job.status === 'completed' ? 'Recovery verification remains separate from execution'
          : main.currentWork,
      time: main.resolved ? time : job.status === 'completed' ? job.completedAt || time : time,
      source: job.id || main.currentAgent, fresh: true,
      domainId: MONITORING_CONTEXT.mainDomain, incident: 'interface', target: interfaceTarget,
    });
  } else {
    if (!state.critical) updates.push({
      id: 'reachability-source', kind: 'source', tone: state.critical ? 'negative' : 'positive',
      title: state.critical ? 'Router reachability exception' : 'Reachability checks current',
      detail: state.critical ? 'XR-PE-E2 unreachable · Separate source condition'
        : 'All routers reachable in the current source snapshot',
      time, source: 'Independent reachability checks', fresh: true,
      domainId: state.critical ? MONITORING_CONTEXT.criticalDomain : null,
      ...(state.critical ? { incident: 'device', target: deviceTarget } : {}),
    });
    if (state.gap === 'none') updates.push({
      id: 'topology-source', kind: 'source', tone: 'info',
      title: 'Topology snapshot available', detail: 'Logical connections from BGP-LS inventory',
      time, source: 'BGP-LS topology', fresh: true, domainId: null,
    });
  }
  const primary = incidents[0];
  const mode = primary ? primary.id === 'monitoring' ? 'gap' : 'incident'
    : main.resolved ? 'recovery' : state.frame === 1 ? 'trend' : 'quiet';
  const title = primary ? primary.id === 'device' ? 'Router reachability needs attention'
    : primary.id === 'monitoring' ? 'Monitoring coverage incomplete'
      : primary.sourceState === 'Source-cleared' ? 'Response follow-up remains open' : 'Interface condition active'
    : main.resolved ? 'Network recovery verified'
      : state.frame === 1 ? 'A utilization trend is developing' : 'Network within configured limits';
  const detail = primary ? `${domainLabel(primary.domainId)} · ${primary.currentWork}`
    : main.resolved ? 'Source evidence and the completed response remain available.'
      : state.frame === 1 ? `${domainLabel(MONITORING_CONTEXT.mainDomain)} · ${reading.utilization}% outbound utilization · Below the ${THRESHOLD}% threshold`
        : 'Current reachability, collection, and interface observations support the watch.';
  return {
    mode, title, detail,
    tone: primary ? primary.id === 'device' ? 'negative' : primary.id === 'monitoring' ? 'inactive' : 'warning'
      : main.resolved || state.frame === 0 ? 'positive' : 'info',
    incidents, updates: updates.slice(0, 4), fresh: state.gap === 'none',
  };
}
